:root {
  --bg: #f0f4f8;
  --card-bg: #ffffff;
  --text: #1e293b;
  --text-muted: #64748b;
  --border: #cbd5e1;
  --accent: #2a9d8f;
  --accent-dark: #1f7a6f;
  --cell-empty: #f8fafc;
  --cell-border: #e2e8f0;
  --focus: #e63946;
  --radius: 12px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: -12px 0 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.grid {
  display: grid;
  grid-template-columns: repeat(16, 1fr);
  gap: 2px;
  aspect-ratio: 1 / 1;
  width: 100%;
  background: var(--cell-border);
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 2px;
  touch-action: manipulation;
}

.cell {
  background: var(--cell-empty);
  border: none;
  border-radius: 2px;
  cursor: pointer;
  padding: 0;
  transition: transform 0.05s ease, background-color 0.1s ease;
  min-width: 0;
  min-height: 0;
}

.cell:hover {
  transform: scale(1.15);
  z-index: 1;
  box-shadow: 0 0 0 2px var(--accent);
}

.cell:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
  z-index: 2;
}

.cell:active {
  transform: scale(0.9);
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

.swatch {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 3px solid transparent;
  background: var(--swatch-color);
  cursor: pointer;
  padding: 0;
  transition: transform 0.1s ease, border-color 0.1s ease, box-shadow 0.1s ease;
}

.swatch:hover {
  transform: scale(1.1);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.swatch:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.swatch:active {
  transform: scale(0.95);
}

.swatch.selected {
  border-color: var(--text);
  box-shadow: 0 0 0 3px var(--card-bg), 0 0 0 6px var(--accent);
}

.tool, .clear {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 18px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: var(--card-bg);
  color: var(--text);
  cursor: pointer;
  transition: background-color 0.1s ease, border-color 0.1s ease, transform 0.05s ease;
  min-height: 44px;
}

.tool:hover, .clear:hover {
  background: #f1f5f9;
  border-color: var(--accent);
}

.tool:focus-visible, .clear:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tool:active, .clear:active {
  transform: scale(0.97);
}

.tool[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent-dark);
  color: #fff;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
}

.count {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-muted);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .swatch {
    width: 38px;
    height: 38px;
  }
  .tool, .clear {
    font-size: 0.9rem;
    padding: 8px 14px;
  }
}

(function() {
  'use strict';

  const GRID_SIZE = 16;
  const gridEl = document.getElementById('grid');
  const countEl = document.getElementById('count');
  const clearBtn = document.getElementById('clear');
  const eraserBtn = document.getElementById('eraser');
  const swatches = Array.from(document.querySelectorAll('.swatch'));

  let selectedColor = swatches[0].dataset.color;
  let isErasing = false;

  // Create grid cells
  const cells = [];
  for (let i = 0; i < GRID_SIZE * GRID_SIZE; i++) {
    const cell = document.createElement('button');
    cell.className = 'cell';
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Cell ${Math.floor(i / GRID_SIZE) + 1}, ${(i % GRID_SIZE) + 1}`);
    cell.dataset.painted = 'false';
    cell.tabIndex = i === 0 ? 0 : -1;
    gridEl.appendChild(cell);
    cells.push(cell);
  }

  function updateCount() {
    const painted = cells.filter(c => c.dataset.painted === 'true').length;
    countEl.textContent = `Painted: ${painted}`;
  }

  function paintCell(cell) {
    if (isErasing) {
      cell.style.backgroundColor = '';
      cell.dataset.painted = 'false';
    } else {
      cell.style.backgroundColor = selectedColor;
      cell.dataset.painted = 'true';
    }
    updateCount();
  }

  // Paint on click
  gridEl.addEventListener('click', (e) => {
    const cell = e.target.closest('.cell');
    if (cell) paintCell(cell);
  });

  // Keyboard navigation and painting
  gridEl.addEventListener('keydown', (e) => {
    const cell = e.target.closest('.cell');
    if (!cell) return;
    const index = cells.indexOf(cell);
    let nextIndex = index;

    switch (e.key) {
      case 'ArrowRight':
        nextIndex = index + 1 < cells.length ? index + 1 : index;
        e.preventDefault();
        break;
      case 'ArrowLeft':
        nextIndex = index - 1 >= 0 ? index - 1 : index;
        e.preventDefault();
        break;
      case 'ArrowDown':
        nextIndex = index + GRID_SIZE < cells.length ? index + GRID_SIZE : index;
        e.preventDefault();
        break;
      case 'ArrowUp':
        nextIndex = index - GRID_SIZE >= 0 ? index - GRID_SIZE : index;
        e.preventDefault();
        break;
      case 'Enter':
      case ' ':
        e.preventDefault();
        paintCell(cell);
        return;
      default:
        return;
    }

    if (nextIndex !== index) {
      cell.tabIndex = -1;
      cells[nextIndex].tabIndex = 0;
      cells[nextIndex].focus();
    }
  });

  // Palette selection
  swatches.forEach(swatch => {
    swatch.addEventListener('click', () => {
      selectedColor = swatch.dataset.color;
      isErasing = false;
      swatches.forEach(s => {
        s.classList.remove('selected');
        s.setAttribute('aria-pressed', 'false');
      });
      swatch.classList.add('selected');
      swatch.setAttribute('aria-pressed', 'true');
      eraserBtn.setAttribute('aria-pressed', 'false');
      eraserBtn.classList.remove('active');
    });
  });

  // Eraser toggle
  eraserBtn.addEventListener('click', () => {
    isErasing = !isErasing;
    eraserBtn.setAttribute('aria-pressed', String(isErasing));
    eraserBtn.classList.toggle('active', isErasing);
    swatches.forEach(s => {
      s.classList.remove('selected');
      s.setAttribute('aria-pressed', 'false');
    });
  });

  // Clear all
  clearBtn.addEventListener('click', () => {
    cells.forEach(cell => {
      cell.style.backgroundColor = '';
      cell.dataset.painted = 'false';
    });
    updateCount();
  });

  // Focus management: ensure only one cell has tabIndex 0
  gridEl.addEventListener('focusin', (e) => {
    const cell = e.target.closest('.cell');
    if (!cell) return;
    cells.forEach(c => { c.tabIndex = -1; });
    cell.tabIndex = 0;
  });

  // Initialize count
  updateCount();
})();
